// Bài 11.5 — số di động: neo hai đầu, KHÔNG cờ g (test không được nhớ lastIndex)
const MOBILE = /^0[35789]\d{8}$/;   // đầu · 0 · một trong 3/5/7/8/9 · đúng 8 chữ số · hết

