// Bài 11.5 — đếm từ (hỏng: \b là ASCII, không thoát ký tự đặc biệt)
function countWord(text, word) {
  const re = new RegExp('\\b' + word + '\\b', 'gi');
  return (text.match(re) || []).length;
}

